#include "Plugin.cpp"
#include <iostream>
static std::vector<CapturedPitch> melody(const std::vector<int>& notes){std::vector<CapturedPitch> p;double time=0;for(int n:notes)for(int i=0;i<12;++i){p.push_back({time,float(n)+0.08f*float(std::sin(i*0.6))});time+=1.0/30;}return p;}
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI gui;int failures=0;auto check=[&](bool ok,const char*s){std::cout<<(ok?"PASS ":"FAIL ")<<s<<"\n";if(!ok)++failures;};
 auto majorMap=melody({60,64,67,65,72,71,67,64,62,60,60});auto major=automaticSelection::estimate(majorMap);std::cout<<"major suggestion "<<automaticSelection::name(major)<<" margin "<<major.margin<<"\n";check(major.valid&&major.key==0&&!major.minor,"suggest C major from a supported vocal pitch map");
 auto minor=automaticSelection::estimate(melody({62,65,69,67,74,72,70,69,65,64,62,62}));std::cout<<"minor suggestion "<<automaticSelection::name(minor)<<"\n";check(minor.valid&&minor.key==2&&minor.minor,"suggest D minor from a supported vocal pitch map");
 check(!automaticSelection::estimate(melody({60,60,60})).valid,"refuse to guess a key from one repeated note");check(!automaticSelection::estimate(melody({60,61,62,63,64,65,66,67,68,69,70,71})).valid,"refuse unsupported major/minor guess for a chromatic map");
 auto ambiguous=automaticSelection::estimate(melody({60,62,64,65,67,69,71}));check(ambiguous.valid&&ambiguous.uncertain,"mark ambiguous relative scales as uncertain");
 automaticSelection::Scale cMajor;cMajor.key=0;cMajor.valid=true;auto selected=automaticSelection::build(melody({61,61,61,61,61,61,61,61}),1,2,cMajor,1,0,5);check(!selected.empty(),"build correction curves for a selected voiced interval");bool inside=true;for(const auto& c:selected)for(const auto& p:c.nodes)inside&=p.time>=1&&p.time<=2;check(inside,"automatic curves stay within selection boundaries");
 ManualDocument doc;doc.setRange(0,3,1);doc.setCurve(0,{{0,60},{3,62}});auto before=doc.save();check(doc.replaceSelection(1,2,selected,0,0,1),"apply automatic selection as an atomic edit");auto e=doc.getEdits();check(e.size()==2&&e[0].end==1&&e[1].start==2,"automatic preserves manual adjustments outside selection");doc.undo();check(doc.getEdits().size()==1&&doc.getCurves().size()==1&&doc.lastAutoKey.load()==-1,"one undo restores complete pre-automatic state");
 doc.replaceSelection(1,2,selected,0,0,1);ManualDocument recall;recall.restore(doc.save());check(recall.lastAutoKey.load()==0&&recall.lastAutoUncertain.load()==1&&recall.getCurves().size()==doc.getCurves().size(),"automatic key suggestion and curves persist");
 NaturalEngine engine;engine.prepare(48000,1);ManualSnapshot snapshot;ManualDocument renderDoc;renderDoc.replaceSelection(1,2,selected,0,0,0);renderDoc.readForAudio(snapshot);TuneSettings settings;settings.amount=0;
 int block=257,count=160000;juce::AudioBuffer<float> audio(1,count+engine.latency+512);audio.clear();for(int offset=0;offset<count+engine.latency;offset+=block){juce::AudioBuffer<float>b(1,block);for(int i=0;i<block;++i)b.setSample(0,i,float(0.2*std::sin(2*juce::MathConstants<double>::pi*277.182631*(offset+i)/48000)));engine.process(b,settings,&snapshot,offset/48000.);audio.copyFrom(0,offset,b,0,0,block);}
 auto pitch=[&](double t){VoiceDetector d;d.prepare(48000);for(int i=int(t*48000)+engine.latency;i<int((t+.25)*48000)+engine.latency;++i)d.push(audio.getSample(0,i));d.analyse();return d.midi;};float original=pitch(.4),corrected=pitch(1.3),later=pitch(2.4);std::cout<<"automatic audio "<<original<<" / "<<corrected<<" / "<<later<<"\n";check(std::abs(corrected-60)<0.1,"automatic selection corrects actual C sharp audio into C major");check(std::abs(original-61)<0.1&&std::abs(later-61)<0.1,"automatic does not change other occurrences outside selection");
 FineProcessor processor;processor.prepareToPlay(48000,256);processor.manual.capturing=true;majorMap[32].midi=61;for(const auto& p:majorMap)processor.manual.push(p);processor.manual.capturing=false;processor.manual.drain();std::unique_ptr<juce::AudioProcessorEditor> editor(processor.createEditor());editor->setVisible(true);ManualPanel* panel=nullptr;
 for(auto* child:editor->getChildren())if(auto* f=dynamic_cast<FinePanel*>(child))for(auto* c:f->getChildren()){if(auto* m=dynamic_cast<ManualPanel*>(c))panel=m;if(auto* b=dynamic_cast<juce::TextButton*>(c))if(b->getButtonText()=="Manual por trecho"){b->setToggleState(true,juce::dontSendNotification);b->onClick();}}
 if(panel){panel->timerCallback();juce::TextButton *all=nullptr,*button=nullptr,*undo=nullptr;for(auto* c:panel->getChildren())if(auto* b=dynamic_cast<juce::TextButton*>(c)){if(b->getButtonText()=="Selecionar tudo")all=b;if(b->getButtonText()=="AUTOMATIC")button=b;if(b->getButtonText()=="Desfazer")undo=b;}
  check(button&&!button->isEnabled(),"AUTOMATIC requires an explicit voice selection");if(all&&button){all->onClick();check(button->isEnabled(),"select all enables AUTOMATIC");button->onClick();check(processor.manual.lastAutoKey.load()>=0&&!processor.manual.getCurves().empty(),"AUTOMATIC button estimates and applies the selected voice");bool showsScale=false;for(auto* c:panel->getChildren())if(auto* combo=dynamic_cast<juce::ComboBox*>(c))if(combo->getNumItems()==25)showsScale=combo->getText().contains("C maior");check(showsScale,"detected scale is visible beside AUTOMATIC");
   if(argc>1){auto path=juce::File(argv[1]);path.deleteFile();juce::FileOutputStream stream(path);juce::PNGImageFormat().writeImageToStream(editor->createComponentSnapshot(editor->getLocalBounds(),true,1),stream);}
   if(undo)undo->onClick();check(processor.manual.getCurves().empty()&&processor.manual.lastAutoKey.load()==-1,"UI undo reverses AUTOMATIC in one step");for(auto* c:panel->getChildren())if(auto* combo=dynamic_cast<juce::ComboBox*>(c))if(combo->getNumItems()==25)combo->setSelectedId(7,juce::dontSendNotification);button->onClick();check(processor.manual.lastAutoKey.load()==2&&processor.manual.lastAutoMinor.load()==1,"user can override guessed scale with D minor before AUTOMATIC");}
 }else check(false,"manual panel available");editor.reset();return failures?1:0;}
